<section class="admin-v2-page-intro"><div><span class="admin-v2-eyebrow">WRITER ACCOUNTS</span><h2>حسابات الكتّاب</h2><p>القيود هنا منفصلة: تعليق صلاحيات الكاتب لا يساوي حظر تسجيل الدخول، وإخفاء الملف لا يحذف المحتوى.</p></div><form class="admin-v2-filter" method="get"><input name="q" value="<?=e($q)?>" placeholder="بحث بالاسم أو المستخدم أو البريد"><select name="status"><option value="">كل حالات الحساب</option><?php foreach(['active'=>'نشط','blocked'=>'محظور','pending'=>'معلق'] as $key=>$label):?><option value="<?=e($key)?>" <?=$status===$key?'selected':''?>><?=e($label)?></option><?php endforeach;?></select><button class="admin-v2-button primary" type="submit">بحث</button></form></section>
<section class="admin-v2-table-panel"><div class="admin-v2-table-wrap"><table class="admin-v2-table"><thead><tr><th>الكاتب</th><th>الحالة</th><th>القيود</th><th>الملف العام</th><th>آخر دخول</th><th>إدارة</th></tr></thead><tbody><?php if(!$rows):?><tr><td colspan="6"><div class="admin-v2-empty">لا توجد حسابات كتّاب مطابقة.</div></td></tr><?php else: foreach($rows as $row):?><tr><td><strong><?=e((string)$row['name'])?></strong><small>@<?=e((string)$row['username'])?> · <?=e((string)$row['email'])?></small></td><td><span class="admin-v2-badge <?=e((string)$row['status'])?>"><?=e((string)$row['status'])?></span><?php if(!empty($row['account_trashed_at'])):?><span class="admin-v2-badge danger">سلة المحذوفات</span><?php endif;?></td><td><?php if(!empty($row['writer_suspended_until'])&&strtotime((string)$row['writer_suspended_until'])>time()):?><span class="admin-v2-badge warning">تعليق حتى <?=e($row['writer_suspended_until'])?></span><?php endif;?><?php if(!empty($row['login_banned_until'])&&strtotime((string)$row['login_banned_until'])>time()):?><span class="admin-v2-badge danger">حظر حتى <?=e($row['login_banned_until'])?></span><?php endif;?></td><td><?=!empty($row['writer_directory_hidden'])?'<span class="admin-v2-badge warning">مخفي</span>':'<span class="admin-v2-badge good">ظاهر</span>'?></td><td><?=e((string)($row['last_login_at']??'—'))?></td><td><details class="admin-v2-actions"><summary>إدارة</summary><form method="post" action="/admin-v2/writers/action"><?=csrf_field()?><input type="hidden" name="id" value="<?=e($row['id'])?>"><label>السبب<textarea name="reason" rows="2"></textarea></label><div class="admin-v2-duration"><input type="number" name="duration_value" min="1" max="8760" placeholder="المدة"><select name="duration_unit"><option value="hours">ساعات</option><option value="days">أيام</option></select></div><div class="admin-v2-action-grid"><button name="action" value="suspend" type="submit">تعليق الكاتب</button><button name="action" value="unsuspend" type="submit">إزالة التعليق</button><button name="action" value="ban" type="submit" class="danger">حظر الدخول</button><button name="action" value="unban" type="submit">إزالة الحظر</button><button name="action" value="<?=!empty($row['writer_directory_hidden'])?'restore_profile':'hide'?>" type="submit"><?=!empty($row['writer_directory_hidden'])?'إظهار الملف':'إخفاء الملف'?></button><button name="action" value="<?=!empty($row['account_trashed_at'])?'restore':'trash'?>" type="submit" class="<?=!empty($row['account_trashed_at'])?'good':'danger'?>"><?=!empty($row['account_trashed_at'])?'استعادة الحساب':'نقل إلى السلة'?></button></div></form></details></td></tr><?php endforeach; endif;?></tbody></table></div></section>
